-- Create "hooks_rollout_stages" table
CREATE TABLE "hooks_rollout_stages" (
  "id" uuid NOT NULL DEFAULT generate_uuidv7(),
  "seq" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "version" integer NOT NULL,
  "percent" integer NOT NULL,
  "state" text NOT NULL,
  "reason" text NULL,
  "set_by" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT clock_timestamp(),
  "updated_at" timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY ("id"),
  CONSTRAINT "hooks_rollout_stages_set_by_check" CHECK (set_by <> ''::text),
  CONSTRAINT "hooks_rollout_stages_state_check" CHECK (state <> ''::text)
);
-- Create index "hooks_rollout_stages_seq_key" to table: "hooks_rollout_stages"
CREATE UNIQUE INDEX "hooks_rollout_stages_seq_key" ON "hooks_rollout_stages" ("seq");
-- Set comment to column: "id" on table: "hooks_rollout_stages"
COMMENT ON COLUMN "hooks_rollout_stages"."id" IS '@access: confidential';
-- Set comment to column: "seq" on table: "hooks_rollout_stages"
COMMENT ON COLUMN "hooks_rollout_stages"."seq" IS '@access: confidential';
-- Set comment to column: "version" on table: "hooks_rollout_stages"
COMMENT ON COLUMN "hooks_rollout_stages"."version" IS 'Hooks generator version being rolled out.
@access: confidential';
-- Set comment to column: "percent" on table: "hooks_rollout_stages"
COMMENT ON COLUMN "hooks_rollout_stages"."percent" IS 'Share of organizations following the default pin, from 0 to 100, cleared for version.
@access: confidential';
-- Set comment to column: "state" on table: "hooks_rollout_stages"
COMMENT ON COLUMN "hooks_rollout_stages"."state" IS 'running, paused, completed or cancelled.
@access: confidential';
-- Set comment to column: "reason" on table: "hooks_rollout_stages"
COMMENT ON COLUMN "hooks_rollout_stages"."reason" IS 'Why the rollout was paused or cancelled, when it was. Free text from staff or the rollout workflow.
@access: opaque-restricted';
-- Set comment to column: "set_by" on table: "hooks_rollout_stages"
COMMENT ON COLUMN "hooks_rollout_stages"."set_by" IS 'Email of the staff operator who made the change, or the rollout workflow.
@access: confidential-pii';
-- Set comment to column: "created_at" on table: "hooks_rollout_stages"
COMMENT ON COLUMN "hooks_rollout_stages"."created_at" IS '@access: confidential';
-- Set comment to column: "updated_at" on table: "hooks_rollout_stages"
COMMENT ON COLUMN "hooks_rollout_stages"."updated_at" IS '@access: confidential';
